/**
 * @description What happens to an outbound transaction around its callout: loading its event and connection,
 * building payloads, failures (a temporary one is planned for auto-retry when the event allows it), and the response
 * handler.
 * @group Integration Hub
 */
public with sharing class IntegrationHubOutcome {

    private static final Integer PAYLOAD_FIELD_MAX = 131072;
    private static final String TRUNCATED_MARK = '...[truncated:';

    /**
     * @description Events of these transactions.
     * @param txns the transactions
     * @return events by Id
     */
    public static Map<Id, IH_Event__c> events(List<IH_Transaction__c> txns) {
        Set<Id> eventIds = new Set<Id>();
        for (IH_Transaction__c t : txns) {
            eventIds.add(t.Event__c);
        }
        return new Map<Id, IH_Event__c>((List<IH_Event__c>) IntegrationHubData.query(
            'SELECT Id, Event_Key__c, Active__c, Related_Object__c, Connection__c, Path__c, Http_Method__c, Payload_Fields__c, Payload_Source__c, Payload_Class__c, '
            + 'Transaction_Id_Key__c, Expects_Callback__c, Response_Handler_Class__c, Business_Data_In_Response__c, '
            + 'Auto_Retry_Max__c, Retry_After_Minutes__c FROM IH_Event__c WHERE Id IN :ids', new Map<String, Object>{ 'ids' => eventIds }));
    }

    /**
     * @description Connections of these events.
     * @param evs the events
     * @return connections by Id
     */
    public static Map<Id, IH_Connection__c> connections(List<IH_Event__c> evs) {
        Set<Id> connIds = new Set<Id>();
        for (IH_Event__c e : evs) {
            connIds.add(e.Connection__c);
        }
        return new Map<Id, IH_Connection__c>((List<IH_Connection__c>) IntegrationHubData.query(
            'SELECT Id, Name, Named_Credential__c, Active__c, Timeout_Seconds__c, Headers__c, Connection_Type__c, Auth_Class__c '
            + 'FROM IH_Connection__c WHERE Id IN :ids',
            new Map<String, Object>{ 'ids' => connIds }));
    }

    /**
     * @description Runs the events' response handlers for the deliveries that got a reply. A handler error marks
     * the transaction Failed. For an event with Business Data In Response the handler does not run here: the
     * transaction gets Business Status Processing and its Id is returned for the background job.
     * @param deliveries the deliveries
     * @return the transactions to hand to IntegrationHubBusiness (empty when none)
     */
    public static List<Id> runHandlers(List<IntegrationHubCallout.Delivery> deliveries) {
        List<Id> background = new List<Id>();
        for (IntegrationHubCallout.Delivery d : deliveries) {
            if (d.res == null || d.ev == null || String.isBlank(d.ev.Response_Handler_Class__c)) {
                continue;
            }
            if (d.ev.Business_Data_In_Response__c == true) {
                if (d.ev.Expects_Callback__c != true || IntegrationHubBusiness.dataOf(d.res.getBody()) != null) {
                    d.txn.Business_Status__c = IntegrationHubBusiness.PROCESSING;
                    background.add(d.txn.Id);
                }
                continue;
            }
            IntegrationHub.ResponseContext ctx = new IntegrationHub.ResponseContext();
            ctx.txn = d.txn;
            ctx.transactionId = d.txn.Id;
            ctx.relatedRecordId = d.txn.Related_Record_Id__c;
            ctx.httpStatus = d.res.getStatusCode();
            ctx.body = d.res.getBody();
            ctx.data = IntegrationHubBusiness.dataOf(ctx.body);
            String error = runHandler(d.ev.Response_Handler_Class__c, ctx);
            if (error != null) {
                failPermanent(d.txn, error);
            }
        }
        return background;
    }

    /**
     * @description Runs one response handler.
     * @param className the class implementing IntegrationHub.IResponseHandler
     * @param ctx the reply or callback
     * @return null when it ran, otherwise the error
     */
    public static String runHandler(String className, IntegrationHub.ResponseContext ctx) {
        if (String.isBlank(className)) {
            return null;
        }
        try {
            ((IntegrationHub.IResponseHandler) IntegrationHub.createInstance(className)).handle(ctx);
            return null;
        } catch (Exception e) {
            return 'Response handler ' + className + ': ' + e.getMessage();
        }
    }

    /**
     * @description A temporary failure without its event: Failed, retried by hand only.
     * @param t the transaction
     * @param message the error
     */
    public static void failTransient(IH_Transaction__c t, String message) {
        failTransient(t, null, message);
    }

    /**
     * @description A temporary failure (timeout, 408, 429, 5xx, a callout error, a send job that stopped). The
     * transaction is Failed; IntegrationHubRetryPlan.planRetry sets Next Retry At when the event's Auto Retry Max allows
     * another try, otherwise the message says it can be retried by hand.
     * @param t the transaction (Auto_Retries__c read)
     * @param ev its event (Auto_Retry_Max__c and Retry_After_Minutes__c read; may be null)
     * @param message the error
     */
    public static void failTransient(IH_Transaction__c t, IH_Event__c ev, String message) {
        IntegrationHubRetryPlan.planRetry(t, ev, message);
    }

    /**
     * @description A permanent failure: the transaction is Failed with the message and is never retried
     * automatically (4xx other than 408 and 429, handler errors, a missing or failing Auth Class, setup problems).
     * @param t the transaction
     * @param message the error
     */
    public static void failPermanent(IH_Transaction__c t, String message) {
        t.Status__c = IntegrationHub.STATUS_FAILED;
        t.Next_Retry_At__c = null;
        IntegrationHub.setError(t, message);
    }

    /**
     * @description Loads events and connections and builds the payloads that need building.
     * @param txns the transactions
     * @return one delivery per transaction
     */
    public static List<IntegrationHubCallout.Delivery> prepare(List<IH_Transaction__c> txns) {
        Map<Id, IH_Event__c> events = events(txns);
        Map<Id, IH_Connection__c> connections = connections(events.values());
        Map<Id, List<IH_Transaction__c>> toBuild = new Map<Id, List<IH_Transaction__c>>();
        List<IntegrationHubCallout.Delivery> deliveries = new List<IntegrationHubCallout.Delivery>();
        for (IH_Transaction__c t : txns) {
            IntegrationHubCallout.Delivery d = new IntegrationHubCallout.Delivery(t, events.get(t.Event__c));
            d.conn = d.ev == null ? null : connections.get(d.ev.Connection__c);
            deliveries.add(d);
            if (d.ev != null && needsBuild(t)) {
                if (!toBuild.containsKey(d.ev.Id)) {
                    toBuild.put(d.ev.Id, new List<IH_Transaction__c>());
                }
                toBuild.get(d.ev.Id).add(t);
            }
        }
        Map<Id, String> fullBodies = new Map<Id, String>();
        for (Id eventId : toBuild.keySet()) {
            fullBodies.putAll(applyBodies(IntegrationHubPayload.build(events.get(eventId), toBuild.get(eventId)), toBuild.get(eventId)));
        }
        for (IntegrationHubCallout.Delivery d : deliveries) {
            useBody(d, fullBodies);
        }
        return deliveries;
    }

    private static void useBody(IntegrationHubCallout.Delivery d, Map<Id, String> fullBodies) {
        Boolean built = fullBodies.containsKey(d.txn.Id);
        d.body = built ? fullBodies.get(d.txn.Id) : d.txn.Request_Payload__c;
        d.payloadUsed = built ? 'New' : 'Original';
    }

    private static Boolean needsBuild(IH_Transaction__c t) {
        return t.Rebuild_Payload__c == true || String.isBlank(t.Request_Payload__c) || t.Request_Payload__c.contains(TRUNCATED_MARK);
    }

    private static Map<Id, String> applyBodies(IntegrationHubPayload.Result built, List<IH_Transaction__c> txns) {
        Map<Id, String> full = new Map<Id, String>();
        for (IH_Transaction__c t : txns) {
            String body = built.bodies.get(t.Id);
            full.put(t.Id, body);
            t.Request_Payload__c = storedCopy(body);
            t.Rebuild_Payload__c = false;
            if (built.errors.containsKey(t.Id)) {
                failPermanent(t, built.errors.get(t.Id));
            }
        }
        return full;
    }

    /**
     * @description The copy of a payload kept on the transaction. A payload longer than the field is sent in full;
     * the stored copy is cut and marked, and a later retry builds the payload again instead of re-sending the copy.
     * @param body the full payload
     * @return the text to store in Request_Payload__c
     */
    @TestVisible
    private static String storedCopy(String body) {
        if (body == null || body.length() <= PAYLOAD_FIELD_MAX) {
            return body;
        }
        String note = '\n' + TRUNCATED_MARK + ' ' + body.length() + ' characters; the full payload was sent]';
        return body.left(PAYLOAD_FIELD_MAX - note.length()) + note;
    }
}
